\section{Determinism and thickening}

\begin{proposition}[Exact determinism]
$T_n$ is a deterministic function of $x$, so $I(x;T_n)=\HT(n)$: the mutual information between $p \bmod f$ and the splitting type of $p$ in $\Q(\zeta_f)$ equals $H(T)$ exactly.
\end{proposition}

\begin{proposition}[Thickening is free]\label{prop:thicken}
$I(p \bmod f^k;T)=I(p\bmod f;T)$ for every $k\ge1$.
\end{proposition}

\begin{proof}[Proof sketch]
$T(p)=\ord_f(p)$ factors through the reduction $(\Z/f^k)^\times\to(\Z/f)^\times$, and a variable and any refinement of it carry the same mutual information with a function of the coarse variable.
\end{proof}

\section{The prime-order pair channel in closed form}

Throughout this section $p$ is prime and $n=p$, so $T_p(x)\in\{1,p\}$ with $T_p(x)=1$ iff $x=0$.

\begin{lemma}[Occupation tables]\label{lem:tables}
Order the three unordered pairs as $(1,1),(1,p),(p,p)$. Over all $p^2$ ordered pairs the occupation numbers of $\Pi$ are $[\,1,\ 2(p-1),\ (p-1)^2\,]$, while the conditional tables, each of mass $p$, are
\[
\Pi_0:[\,1,\ 0,\ p-1\,],\qquad \Pi_c:[\,0,\ 2,\ p-2\,]\quad(c\neq0).
\]
\end{lemma}

\begin{proof}[Proof sketch]
$(1,1)$ occurs only at $x=y=0$; $(1,p)$ requires exactly one coordinate to vanish, giving $2(p-1)$ ordered pairs; the rest are $(p,p)$. For the conditionals parametrise the fibre $x+y=c$ by $x$, with $y=c-x$. If $c=0$ then $y=0$ iff $x=0$: the split state occurs once, $(p,p)$ on the remaining $p-1$ values, and the mixed state cannot occur. If $c\neq0$ the mixed state occurs exactly at the two distinct values $x=0$ and $x=c$, and $(p,p)$ on the remaining $p-2$; the split state cannot occur since $x=y=0$ would force $c=0$.
\end{proof}

\begin{theorem}[Exact prime-order pair channel]\label{thm:closed}
For every prime $p$,
\[
\Ipair(p)=\log_2 p-\frac{(p-1)(2p-1)}{p^{2}}\log_2(p-1)+\frac{(p-1)(p-2)}{p^{2}}\log_2(p-2),
\]
the last term being $0$ at $p=2$, where its coefficient vanishes.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:tables} and $H=\log_2 M-\frac1M\sum_i c_i\log_2 c_i$ for occupation numbers $c_i$ of mass $M$:
\[
H(\Pi)=2\log_2 p-\frac1{p^2}\Big(2(p-1)+2p(p-1)\log_2(p-1)\Big),
\]
\[
H(\Pi_0)=\log_2 p-\frac{p-1}{p}\log_2(p-1),\qquad
H(\Pi_c)=\log_2 p-\frac1p\Big(2+(p-2)\log_2(p-2)\Big).
\]
Averaging the conditionals with weights $\frac1p$ and $\frac{p-1}{p}$ and subtracting from $H(\Pi)$ cancels the $2(p-1)/p^2$ terms and combines the coefficients of $\log_2(p-1)$ into $-\frac{(p-1)(2p-1)}{p^2}$.
\end{proof}

Checks: $p=2$ gives $1$; $p=3$ gives $\log_23-\tfrac{10}{9}=0.47385\ldots$; $p=5$ gives $0.20271\ldots$, all matching direct enumeration.

\begin{theorem}[Algebraic split]\label{thm:split}
For every prime $p$,
\[
\Ipair(p)=\big(\log_2 p-\log_2(p-1)\big)+\frac{\log_2(p-1)}{p^{2}}
-\frac{(p-1)(p-2)}{p^{2}}\big(\log_2(p-1)-\log_2(p-2)\big).
\]
\end{theorem}

\begin{theorem}[Upper envelope]\label{thm:envelope}
For every prime $p$, $\displaystyle \Ipair(p)\le\log_2 p-\log_2(p-1)+\frac{\log_2(p-1)}{p^{2}}$.
\end{theorem}

\begin{proof}[Proof sketch]
Expanding Theorem~\ref{thm:split} and matching coefficients recovers Theorem~\ref{thm:closed}; the envelope follows by discarding the nonnegative last term.
\end{proof}

\begin{theorem}[Quadratic two-sided bounds]\label{thm:asym}
For every odd prime $p$,
\[
\frac{1}{p^{2}\ln 2}\ \le\ \Ipair(p)\ \le\ \frac{\log_2 p+5}{p^{2}},
\]
and in particular $\Ipair(p)>0$: the prime-order channel is never exactly silent. Moreover $\Ipair(p)<3/(p-1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply $\frac{x-y}{x}\le\ln\frac xy\le\frac{x-y}{y}$ $(0<y\le x)$ to both logarithm differences in Theorem~\ref{thm:split}. For the lower bound, $\log_2 p-\log_2(p-1)\ge\frac1{p\ln2}$ and $\log_2(p-1)-\log_2(p-2)\le\frac1{(p-2)\ln2}$, so
\[
\Ipair(p)\ \ge\ \frac1{p\ln2}-\frac{p-1}{p^2\ln2}+\frac{\log_2(p-1)}{p^2}=\frac{1}{p^2\ln2}+\frac{\log_2(p-1)}{p^2}.
\]
Reversing both estimates gives $\Ipair(p)\le\frac{3p-2}{(p-1)p^2\ln2}+\frac{\log_2(p-1)}{p^2}$, and $\frac{3p-2}{(p-1)\ln2}\le5$ for $p\ge3$ with room to spare. The bound $3/(p-1)$ follows from Theorem~\ref{thm:envelope}.
\end{proof}

\begin{theorem}[Sub-cap theorem]\label{thm:subcap}
$\Ipair(p)<1$ for every odd prime $p$.
\end{theorem}

\begin{proof}[Proof sketch]
For $p\ge5$, $\Ipair(p)<3/(p-1)\le3/4<1$; the case $p=3$ is the explicit value $0.4739\ldots$.
\end{proof}

\begin{theorem}[Uniqueness of the extremal prime]
For a prime $p$, $\Ipair(p)=1$ if and only if $p=2$.
\end{theorem}

\begin{corollary}[Localisation of the cap-breaking]
Exhaustive evaluation gives $\Ipair(n)>1$ for $n=4,6,8,10,12,14,16$, while Theorem~\ref{thm:subcap} forbids it for every prime order. Hence exceeding the binary-fork cap is not a matter of the \emph{size} of the Galois group but of the \emph{divisor structure} of its order.
\end{corollary}

\section{Multiplicative structure}

\begin{theorem}[CRT factorisation of the type]\label{thm:crt}
Let $m,n$ be coprime and $a$ any integer. Then $T_{mn}(a)=T_m(a)T_n(a)=\lcmop\big(T_m(a),T_n(a)\big)$.
\end{theorem}

\begin{proof}[Proof sketch]
Coprimality gives $\gcd(mn,a)=\gcd(m,a)\gcd(n,a)$, whence the product formula; since $T_m(a)\mid m$ and $T_n(a)\mid n$ the factors are coprime, so their product is their lcm.
\end{proof}

\begin{theorem}[Coprime additivity of the type entropy]\label{thm:add}
For all $m,n\ge1$ with $\gcd(m,n)=1$, $\HT(mn)=\HT(m)+\HT(n)$.
\end{theorem}

\begin{proof}[Proof sketch]
Under the Chinese Remainder isomorphism a uniform element of $C_{mn}$ is a pair of independent uniform elements of $C_m$ and $C_n$, and by Theorem~\ref{thm:crt} the type variable of $C_{mn}$ is the pair $(T_m,T_n)$ up to the bijection $(u,v)\mapsto uv$ on coprime pairs of divisors; entropies of independent variables add. Concretely, \eqref{eq:HT} with multiplicativity of $\varphi$ and $\sum_{d\mid mn}=\sum_{i\mid m}\sum_{j\mid n}$ (with $d=ij$) splits the log-sum.
\end{proof}

\begin{theorem}[Sylow decomposition]\label{thm:sylow}
For $n\ge1$, $\displaystyle \HT(n)=\sum_{p\mid n}\HT\big(p^{v_p(n)}\big)$, with $\HT(1)=0$.
\end{theorem}

\begin{corollary}[Squarefree formula]
If $n$ is squarefree then $\displaystyle \HT(n)=\sum_{p\mid n}\Big(\log_2 p-\frac{p-1}{p}\log_2(p-1)\Big)$.
\end{corollary}

\begin{corollary}[Monotonicity]
If $d\mid n$ with $\gcd(d,n/d)=1$ then $\HT(d)\le\HT(n)$: adding prime factors to the Galois order never destroys splitting information.
\end{corollary}

\section{The $2$-adic tower saturates at two bits}

\begin{theorem}[$2$-adic closed form]\label{thm:twoadic}
For every $k\ge0$, $\HT(2^k)=2-2^{\,1-k}$. The sequence is strictly increasing, never attains $2$, and converges to $2$.
\end{theorem}

\begin{proof}[Proof sketch]
The divisors of $2^k$ are $2^j$, $0\le j\le k$, with $\varphi(2^j)=2^{j-1}$ for $j\ge1$. Induction gives $\sum_{j=0}^k\varphi(2^j)\log_2\varphi(2^j)=(k-2)2^k+2$; substituting into \eqref{eq:HT} yields $k-2^{-k}\big((k-2)2^k+2\big)=2-2^{1-k}$.
\end{proof}

Thus the $2$-primary part of any cyclic Galois group contributes at most two bits, however deep the tower. Combined with Theorem~\ref{thm:sylow}: \emph{depth saturates, breadth accumulates}.

\section{The divisor-lattice ceiling}

\begin{lemma}
For $n\ge3$ the divisor count satisfies $d(n)<n$; for $n\in\{1,2\}$, $d(n)=n$.
\end{lemma}

\begin{theorem}[Residue ceiling]
$\HT(n)\le\log_2 n$ for $n\ge1$, strictly for $n\ge3$.
\end{theorem}

\begin{theorem}[Divisor-lattice ceiling]\label{thm:divbound}
$\HT(n)\le\log_2 d(n)$ for $n\ge1$, strictly for $n\ge3$.
\end{theorem}

\begin{proof}[Proof sketch]
The type law is supported on the $d(n)$ divisors of $n$, and the entropy of a law on a finite set is at most the logarithm of its cardinality, with equality iff the law is uniform. For $n\ge3$ uniformity fails, since $\Prob(T=1)=1/n<\varphi(n)/n=\Prob(T=n)$.
\end{proof}

\begin{corollary}[The sandwich]
For $n\ge1$, $\Hnr(n)\le\HT(n)\le\log_2 d(n)$, with both inequalities strict for composite $n\ge3$. Moreover $\HT(n)\ge0$ always, with $\HT(n)>0$ exactly for $n\ge2$.
\end{corollary}

Theorem~\ref{thm:divbound} is the precise sense in which the divisor structure of the cyclic order governs the channel; it also explains the numerical landscape, where $n=12$ (six divisors) outranks the larger $n=16$ (five divisors).

\section{Lossiness of the binary readout}

\begin{theorem}[Data processing]
$\Hnr(n)\le\HT(n)$ for every $n\ge1$.
\end{theorem}

\begin{theorem}[Lossiness dichotomy]\label{thm:lossy}
For $n\ge2$, $\Hnr(n)<\HT(n)$ if and only if $n$ is composite.
\end{theorem}

\begin{proof}[Proof sketch]
For prime $n$ the type takes exactly two values and $\nr$ is a bijective relabelling. For composite $n$ there is a divisor $1<d<n$, so $T$ has at least three states while $\nr$ has two, and merging states of positive probability strictly decreases entropy. Quantitatively $\HT-\Hnr=\frac{n-1}{n}H(T\mid T\neq1)>0$.
\end{proof}

\begin{theorem}[Quantitative decay]\label{thm:nrdecay}
For $n\ge2$, $0\le\Hnr(n)\le\frac{\log_2 n+2}{n}$; hence $\Hnr(n)\to0$.
\end{theorem}

\begin{corollary}[Total loss along the $2$-tower]
$\HT(2^k)-\Hnr(2^k)\to2$: along the $2$-adic tower the binary readout eventually reports none of the two bits carried by the splitting type.
\end{corollary}

\section{Faces of the channel and negative results}

\paragraph{The split-count projection.} Applying \eqref{eq:Ipair} to $\nr$ instead of $T$ gives the classical split-count channel $I_s(n)$. Empirically the projection is faithful ($0.2896$ measured against $I_s(4)=0.2947$; $0.1445$ against $I_s(6)=0.1487$), while the full type channel carries $1.2500$ and $1.4739$ bits: the split-count channel is a strictly smaller face, and the cap that governs it does not govern the whole.

\paragraph{Prime-level pinning of each type face.} Conditioning on a single type value gives a two-state readout of entropy $h_2(\varphi(d)/n)$. For $n=4$ these pinnings are exact: $[T=1]$ has entropy $h_2(1/4)=0.8113$ (measured $0.8098$), $[T=2]$ likewise (measured $0.8110$), and $[T=4]$ has $h_2(1/2)=1.0000$ (measured $1.0000$) --- a prime-level quartic-character pinning. For $n=6$, $[T=1]$ pins at $h_2(1/6)=0.6500$ (measured $0.6497$).

\paragraph{Symmetry, shallowness, scope.} The channel is invariant under exchanging $p$ and $q$; measurements give $0.0001$ bits of which-factor information. By Proposition~\ref{prop:thicken} no information is gained by refining the residue modulo higher powers of $f$, and coprime controls are flat. The results are structural statements about arithmetic information; they do not yield a factoring method.

\section{Algorithms}

\textbf{A. Exhaustive pair-channel evaluation.} For given $n$, iterate over all $n^2$ ordered pairs $(x,y)$, compute the sorted type key, accumulate into $\Pi$ and $\Pi_{x+y}$, and evaluate \eqref{eq:Ipair}; cost $\Theta(n^2)$ time, $O(n\,d(n)^2)$ space.

\textbf{B. Closed-form prime evaluation.} For prime $p$, evaluate Theorem~\ref{thm:closed} in $O(1)$ operations; cross-validating A against B over all primes to a bound certifies the closed form.

\textbf{C. Sylow evaluation.} Factor $n$, evaluate $\HT(p^{v})$ by the totient law over $v+1$ divisors, and sum (Theorem~\ref{thm:sylow}): exponentially faster than enumerating the group for smooth $n$.

\textbf{D. Arithmetic realisation.} For prime $f$, sieve primes $p\neq f$, compute $\ord_f(p)$ by repeated multiplication mod $f$, tabulate type frequencies; for semiprimes, sample pairs, record $N \bmod f$ and the sorted type pair, and estimate \eqref{eq:Ipair} by plug-in entropies.

\section{Discussion}

\subsection{What breaks the cap}

The binary-fork cap is a theorem about a two-state observable whose pair statistics are governed by a product of signs: $\{\varepsilon(p),\varepsilon(q)\}$ is determined up to swap by $\varepsilon(N)$, one bit. Theorem~\ref{thm:closed} shows the quadratic case is the unique prime-order instance attaining that bound, and exactly how it degrades: at larger prime order the type is still two-state, but the group law no longer lets the product class determine the pair, and the information collapses like $p^{-2}$. The escape route is the divisor lattice: for composite $n$ the type is genuinely multi-state and the conditional tables vary far more strongly with $c$, pushing the value above one bit and up to $1.7239$ at $n=12$.

\subsection{An emerging arithmetic thermodynamics}

Read as statistical mechanics on the divisor lattice: the state space is the divisor lattice with occupation law $\varphi(d)/n$; the free entropy $\HT$ is additive over coprime parts and decomposes over Sylow components; depth saturates ($2-2^{1-k}$, never more than two bits); and coarse instruments lose everything, since $\Hnr(n)\le(\log_2n+2)/n\to0$.

\subsection{Conjectural completion}

Exhaustively, for every coprime pair tested,
\[
\Ipair(mn)=\Ipair(m)+\Ipair(n)\qquad(\gcd(m,n)=1),
\]
e.g.\ $\Ipair(12)=0.4739+1.2500=1.7239$, $\Ipair(10)=1+0.2027$, $\Ipair(15)=0.6766$, $\Ipair(20)=1.4527$, $\Ipair(24)=1.7864$; and along the $2$-tower the values $1,\,1.25,\,1.3125,\,1.328125$ match
\[
\Ipair(2^k)=\tfrac43\big(1-4^{-k}\big)
\]
exactly for $k\le4$. The \emph{even} half of the expected classification then follows: an even $n\ge4$ has a $2$-part contributing at least $1.25$ while all other parts are nonnegative. In this sense the cap concerns the $2$-torsion of the Galois group rather than the number of splitting types.

\subsection{An incompatibility}

The \emph{odd} half --- that $\Ipair(n)<1$ for every odd $n\ge3$ --- cannot survive alongside additivity. Under additivity a squarefree odd order satisfies $\Ipair(n)=\sum_{p\mid n}\Ipair(p)$ with each summand given exactly by Theorem~\ref{thm:closed}, and
\[
\sum_{3\le p\le139}\Ipair(p)=1.00010\ldots>1,
\]
the sum over odd primes up to $10^3$ being $1.01134\ldots$ and the full sum $\approx1.0132$. So the odd squarefree order $n=\prod_{3\le p\le139}p$ would carry more than one bit. At most one of the two conjectures can hold as stated; the evidence favours additivity, which is exact on every coprime pair tested (including $\Ipair(15)=0.6766$, $\Ipair(21)=0.5880$, $\Ipair(45)=0.7292$, $\Ipair(105)=0.7907$), whereas the odd half has been checked only for orders with two or three odd prime factors. The corrected statement is:

\begin{conjecture}[Revised dichotomy]
$\Ipair(n)>1$ for every even $n\ge4$; $\Ipair(2)=1$; and $\Ipair(n)<1$ for odd $n$ with $\sum_{p\mid n}\Ipair(p^{v_p})<1$ --- a condition failing only for odd orders with very many distinct prime factors.
\end{conjecture}

\subsection{Limitations}

All statements concern the unordered pair; the channel is provably symmetric and empirically factor-useless. Everything is conditioned on knowing the modulus $f$ and the group law, so nothing here bears on the hardness of factoring. Composite-order values are exhaustive evaluations for the listed orders; the general composite theory remains conjectural.

\section{Future directions}

\begin{enumerate}
\item \textbf{CRT additivity of the pair channel.} Prove $\Ipair(mn)=\Ipair(m)+\Ipair(n)$ for coprime $m,n$. The type map is CRT-multiplicative and the single-prime entropy additive; the missing step is a product decomposition of the conditional tables $\Pi_c$, a purely combinatorial statement.
\item \textbf{The $2$-adic pair law.} Prove $\Ipair(2^k)=\frac43(1-4^{-k})$; with additivity this gives the even half of the classification unconditionally.
\item \textbf{The revised dichotomy.} Determine the exact failure locus on the odd side; deciding whether an odd order with many prime factors really breaks the cap would refute the parity reading of the cap.
\item \textbf{Non-cyclic Galois groups.} The type of a prime in a general extension is the order of its Frobenius class; the divisor lattice becomes the lattice of cyclic subgroups. Which groups maximise the pair channel at fixed order?
\item \textbf{Higher tuples.} Replace semiprimes by products of $k$ primes and study the growth of the $k$-fold channel.
\item \textbf{Effective error terms.} Convert the empirical agreement into a rigorous rate via effective Chebotarev bounds for cyclotomic fields.
\end{enumerate}

\section{Conclusion}

The complete splitting type of a prime in a cyclotomic field is a multi-state observable, and its pair channel is not bounded by the one bit that governs every binary fork. At prime cyclic order the channel is exactly
\[
\log_2 p-\frac{(p-1)(2p-1)}{p^{2}}\log_2(p-1)+\frac{(p-1)(p-2)}{p^{2}}\log_2(p-2),
\]
strictly positive, of order $p^{-2}$, strictly below one bit for every odd prime and exactly one bit at $p=2$. At composite order it exceeds one bit for every even order tested, peaking at $1.7239$ bits for the twelve-element group of $\Q(\zeta_{13})$. Behind both regimes stands the divisor lattice of the Galois order, which bounds the single-prime channel by $\log_2 d(n)$, makes it additive over coprime factorisations, and saturates it at exactly two bits along the $2$-adic tower --- while the binary root-count readout is provably lossy at exactly the composite orders and asymptotically reports nothing at all. The type, not the root count, is the complete object.

