"""Closed-form evaluation and certified envelopes for prime cyclic orders."""

from __future__ import annotations

from math import log, log2
from typing import Dict, Tuple


def i_pair_prime(p: int) -> float:
    """Exact pair-channel capacity of a prime cyclic order p, in bits.

    I_pair(p) = log2 p - ((p-1)(2p-1)/p^2) log2(p-1)
                       + ((p-1)(p-2)/p^2) log2(p-2),
    the last term being 0 at p = 2 where its coefficient vanishes.
    """
    if p == 2:
        return 1.0
    coeff_lo = (p - 1) * (2 * p - 1) / p ** 2
    coeff_hi = (p - 1) * (p - 2) / p ** 2
    return log2(p) - coeff_lo * log2(p - 1) + coeff_hi * log2(p - 2)


def envelopes(p: int) -> Dict[str, float]:
    """All proved bounds for an odd prime order p."""
    return {
        "lower_quadratic": 1.0 / (p ** 2 * log(2.0)),
        "upper_quadratic": (log2(p) + 5.0) / p ** 2,
        "upper_envelope": log2(p) - log2(p - 1) + log2(p - 1) / p ** 2,
        "decay_bound": 3.0 / (p - 1),
    }


def sub_cap_certificate(p: int) -> Tuple[bool, str]:
    """Certify I_pair(p) < 1 for odd p, exhibiting the reason."""
    value = i_pair_prime(p)
    if p == 2:
        return (abs(value - 1.0) < 1e-15, "p = 2 attains the cap exactly")
    if p >= 5:
        return (value < 3.0 / (p - 1) <= 0.75, "decay bound 3/(p-1) <= 3/4")
    return (value < 1.0, "explicit value log2 3 - 10/9 = 0.4739...")


if __name__ == "__main__":
    for p in (2, 3, 5, 7, 11, 13, 101):
        print(p, round(i_pair_prime(p), 9), sub_cap_certificate(p),
              {k: round(v, 8) for k, v in envelopes(p).items()})

"""Sylow evaluation of the splitting-type entropy via coprime additivity."""

from __future__ import annotations

from math import gcd, log2
from typing import Dict, List


def totient(n: int) -> int:
    """Euler's totient, by trial division."""
    result, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result


def factorise(n: int) -> Dict[int, int]:
    """Prime factorisation as {prime: exponent}."""
    out: Dict[int, int] = {}
    m, p = n, 2
    while p * p <= m:
        while m % p == 0:
            out[p] = out.get(p, 0) + 1
            m //= p
        p += 1
    if m > 1:
        out[m] = out.get(m, 0) + 1
    return out


def h_type_prime_power(p: int, v: int) -> float:
    """H_T(p^v) = log2(p^v) - p^{-v} sum_{j<=v} phi(p^j) log2 phi(p^j)."""
    n = p ** v
    s = 0.0
    for j in range(v + 1):
        t = totient(p ** j)
        if t > 1:
            s += t * log2(t)
    return log2(n) - s / n


def h_type(n: int) -> float:
    """H_T(n) = sum over Sylow parts, using coprime additivity.

    For n = 2^k this returns 2 - 2^{1-k} exactly.
    """
    if n <= 1:
        return 0.0
    return sum(h_type_prime_power(p, v) for p, v in factorise(n).items())


def h_rootcount(n: int) -> float:
    """Binary root-count entropy h2(1/n)."""
    if n <= 1:
        return 0.0
    q = 1.0 / n
    return -q * log2(q) - (1 - q) * log2(1 - q)


def divisor_count(n: int) -> int:
    d = 1
    for _, v in factorise(n).items():
        d *= v + 1
    return d


def sandwich(n: int) -> Dict[str, float]:
    """The proved sandwich H_nr(n) <= H_T(n) <= log2 d(n)."""
    return {
        "H_nr": h_rootcount(n),
        "H_T": h_type(n),
        "log2_d": log2(divisor_count(n)),
    }


if __name__ == "__main__":
    for n in (12, 16, 60, 2 ** 10, 5040):
        print(n, {k: round(v, 6) for k, v in sandwich(n).items()})
